    if let k = q4VerifyProjKernels[MT * 8 + SPLIT] { kern = k } else {
        kern = MLXFast.metalKernel(name: "q4_vproj_mt\(MT)_sp\(SPLIT)", inputNames: ["xT", "w", "scales", "biases", "params"], outputNames: [SPLIT == 1 ? "y" : "part"], source: src)
        q4VerifyProjKernels[MT * 8 + SPLIT] = kern
    }
    let xf = x.reshaped(M, K)
    let pr = MLXArray([Int32(M)])   // the row count is a runtime value: one pipeline per row-tile count, not per row count (C-0356)
    let xT = q4VerifyProjTransKernel([xf, pr], template: [("T", x.dtype), ("K", K), ("MP", MP)],
                                     grid: (K * MP, 1, 1), threadGroup: (256, 1, 1), outputShapes: [[K, MP]], outputDTypes: [x.dtype])[0]
    let nsg = (N / 8) * SPLIT
    let tmpl: [(String, any KernelTemplateArg)] = [("T", x.dtype), ("MT", MT), ("MP", MP), ("N", N), ("K", K), ("GS", 64), ("SGPT", SGPT)]
    let grid = (((nsg + SGPT - 1) / SGPT) * SGPT * 32, 1, 1)
    let y: MLXArray
    if SPLIT == 1 {
        y = kern([xT, q.weight, q.scales, b, pr], template: tmpl, grid: grid, threadGroup: (SGPT * 32, 1, 1), outputShapes: [[M, N]], outputDTypes: [x.dtype])[0]
    } else {
        let part = kern([xT, q.weight, q.scales, b, pr], template: tmpl, grid: grid, threadGroup: (SGPT * 32, 1, 1),
                        outputShapes: [[SPLIT, N, MP]], outputDTypes: [.float32])[0]
        y = q4VerifyProjRedKernel([part, pr], template: [("T", x.dtype), ("MP", MP), ("N", N), ("SPLIT", SPLIT)],
                                  grid: (M * N, 1, 1), threadGroup: (256, 1, 1), outputShapes: [[M, N]], outputDTypes: [x.dtype])[0]
    }
    EngineWitness.hit("verify_proj")
    return y.reshaped(Array(x.shape.dropLast()) + [N])
}

/// q4VerifyProj with ENGINE_VERIFY_PROJ_CHECK handled here (for call sites outside q8Proj, e.g. the LM head)
func q4VerifyProjChecked(_ lin: Linear, _ x: MLXArray) -> MLXArray? {
    guard let y = q4VerifyProj(lin, x) else { return nil }
    if !q4VerifyProjCheck { return y }
    let r = lin(x)
    let d = abs(y.asType(.float32) - r.asType(.float32)).max().item(Float.self), a = abs(r.asType(.float32)).max().item(Float.self)
    FileHandle.standardError.write(String(format: "vproj-check rows=%d N=%d K=%d max|d| %.3e max|ref| %.3e\n", x.size / x.dim(-1), y.dim(-1), x.dim(-1), d, a).data(using: .utf8)!)
    return r
}
